1	// Command grammar-refresh vendors a tree-sitter grammar into
2	// internal/sem/grammars/<lang> from its upstream git repository and records
3	// where it came from in internal/sem/grammars/grammars.json. It is a
4	// maintainer tool: it needs the network, and its output is committed, so
5	// building entire-graph never downloads anything.
6	//
7	// Usage:
8	//
9	//	go run ./cmd/grammar-refresh -lang swift -ref 0.7.4-with-generated-files
10	//	go run ./cmd/grammar-refresh -lang fsharp -ref <commit> -path fsharp
11	//	go run ./cmd/grammar-refresh -lang newlang -ref v1.0.0 -url https://github.com/o/tree-sitter-newlang
12	//
13	// The ref must contain generated sources (src/parser.c) built for ABI 13-14,
14	// the range the go-tree-sitter runtime loads. binding.go is never touched, so
15	// a new language still needs one. A grammar that changes parse results needs
16	// an IdentityRevision bump (internal/sem/provider.go) in the same commit.
