29	func main() {
30		var (
31			lang         = flag.String("lang", "", "grammar directory name under -dir (required)")
32			ref          = flag.String("ref", "", "tag, branch or full commit to vendor (required)")
33			url          = flag.String("url", "", "git URL; defaults to the manifest entry")
34			subdir       = flag.String("path", "", "grammar subdirectory within the repository; defaults to the manifest entry")
35			manifestPath = flag.String("manifest", "internal/sem/grammars/grammars.json", "path to the grammar manifest")
36			grammarsDir  = flag.String("dir", "internal/sem/grammars", "directory holding vendored grammars")
37		)
38		flag.Parse()
39		if *lang == "" || *ref == "" {
40			flag.Usage()
41			os.Exit(2)
42		}
43		if err := refresh(*lang, *ref, *url, *subdir, *manifestPath, *grammarsDir); err != nil {
44			fmt.Fprintln(os.Stderr, "grammar-refresh:", err)
45			os.Exit(1)
46		}
47	}
