50	
51	func refresh(lang, ref, url, subdir, manifestPath, grammarsDir string) error {
52		if !languageNamePattern.MatchString(lang) {
53			return fmt.Errorf("invalid -lang %q: use the lower-case directory name under %s", lang, grammarsDir)
54		}
55		if subdir != "" && !filepath.IsLocal(subdir) {
56			return fmt.Errorf("invalid -path %q: must be a relative path inside the repository", subdir)
57		}
58		grammars, err := loadManifest(manifestPath)
59		if err != nil {
60			return err
61		}
62		var existing Grammar
63		for _, g := range grammars {
64			if g.Language == lang {
65				existing = g
66			}
67		}
68		if url == "" {
69			url = existing.URL
70		}
71		if url == "" {
72			return fmt.Errorf("%s is not in %s; pass -url", lang, manifestPath)
73		}
74		if subdir == "" {
75			subdir = existing.Path
76		}
77		if subdir != "" && !filepath.IsLocal(subdir) {
78			return fmt.Errorf("invalid path %q for %s in %s: must be a relative path inside the repository", subdir, lang, manifestPath)
79		}
80	
81		tmp, err := os.MkdirTemp("", "grammar-refresh-")
82		if err != nil {
83			return err
84		}
85		defer os.RemoveAll(tmp)
86		if err := git(tmp, "init", "-q"); err != nil {
87			return err
88		}
89		if err := git(tmp, "fetch", "-q", "--depth", "1", "--", url, ref); err != nil {
90			return fmt.Errorf("fetch %s %s: %w", url, ref, err)
91		}
92		if err := git(tmp, "checkout", "-q", "FETCH_HEAD"); err != nil {
93			return err
94		}
95		revision, err := gitOutput(tmp, "rev-parse", "HEAD")
96		if err != nil {
97			return err
98		}
99	
100		files, abi, err := vendor(tmp, subdir, filepath.Join(grammarsDir, lang))
101		if err != nil {
102			return fmt.Errorf("%s at %s: %w", url, ref, err)
103		}
104		note := ""
105		if existing.Revision == revision {
106			note = existing.Note
107		}
108		grammars = upsert(grammars, Grammar{
109			Language:  lang,
110			URL:       url,
111			Reference: ref,
112			Revision:  revision,
113			Path:      subdir,
114			Files:     files,
115			ABI:       abi,
116			Note:      note,
117		})
118		if err := saveManifest(manifestPath, grammars); err != nil {
119			return err
120		}
121		fmt.Printf("vendored %s %s (%s, ABI %d) into %s\n", lang, ref, revision[:7], abi, filepath.Join(grammarsDir, lang))
122		fmt.Println("next: bump IdentityRevision in internal/sem/provider.go if parse results change, and run scripts/gen-notices.sh")
